// The committed types of the verify API document (`/verify/v1`), generated by
// tools/generate-contracts.ts.

import { readFileSync } from "node:fs";
import { join } from "node:path";

import { describe, expect, it } from "vitest";

const generatedVerifyTypes = (): string =>
  readFileSync(
    join(
      import.meta.dirname,
      "..",
      "packages",
      "contracts",
      "src",
      "generated",
      "verify.ts",
    ),
    "utf8",
  );

describe("the committed verify API types", () => {
  it("type the getRoundVerification operation, its route, and the response", () => {
    const types = generatedVerifyTypes();
    expect(types).toMatch(/^ {2}getRoundVerification: \{$/mu);
    expect(types).toContain(
      '  getRoundVerification: { path: "/verify/v1/rounds/{roundId}"; method: "get" };',
    );
    expect(types).toMatch(/^ {4}RoundVerification: \{$/mu);
    expect(types).toMatch(/^ {4}Kernel: \{$/mu);
  });

  it("leave no interface and name the document they were generated from", () => {
    const types = generatedVerifyTypes();
    expect(types).not.toMatch(/^export interface /mu);
    expect(types).toMatch(
      /^\/\/ Generated by tools\/generate-contracts\.ts from src\/schemas\/verify\.v1\.openapi\.yaml\./u,
    );
  });
});
